    """Replicate the marker's asymmetric pattern at every all-zero matching location."""
    source = [row[:] for row in grid]
    colors = {v for row in source for v in row if v not in (0, 1, 5)}
    if not colors:
        return source
    marker = min(colors)
    pts = [(r, c) for r, row in enumerate(source) for c, v in enumerate(row) if v == marker]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    h, w = len(source), len(source[0])
    matches = []
    for r in range(h):
        for c in range(w):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(0 <= rr < h and 0 <= cc < w and source[rr][cc] == 0 for rr, cc in cells):
                matches.extend(cells)
